+  (void)premature;
+  Curl_safefree(mq->sendleftovers);
+  return CURLE_OK;
+}
+
 static CURLcode mqtt_doing(struct Curl_easy *data, bool *done)
 {
   CURLcode result = CURLE_OK;
   struct connectdata *conn = data->conn;
   struct mqtt_conn *mqtt = &conn->proto.mqtt;
   struct MQTT *mq = data->req.p.mqtt;
   ssize_t nread;
   curl_socket_t sockfd = conn->sock[FIRSTSOCKET];
   unsigned char *pkt = (unsigned char *)data->state.buffer;
   unsigned char byte;

   *done = FALSE;

   if(mq->nsend) {
     /* send the remainder of an outgoing packet */
     char *ptr = mq->sendleftovers;
-    result = mqtt_send(data, mq->sendleftovers, mq->nsend);
+    size_t nsend = mq->nsend;
+    /* detach the leftover from the MQTT struct before attempting to send
+       it again, so that mqtt_send() cannot end up leaving this same
+       (now freed) pointer behind on error */
+    mq->sendleftovers = NULL;
+    mq->nsend = 0;
+    result = mqtt_send(data, ptr, nsend);
     free(ptr);
     if(result)
       return result;
   }

   infof(data, "mqtt_doing: state [%d]", (int) mqtt->state);
   switch(mqtt->state) {
   case MQTT_FIRST:
